from fastapi import FastAPI
from pydantic import BaseModel, computed_field
from fastapi.testclient import TestClient
import json

app = FastAPI()

class Item(BaseModel):
    name: str

    @computed_field
    @property
    def name_upper(self) -> str:
        return self.name.upper()

@app.post("/items/", response_model=Item)
async def create_item(item: Item):
    return item

client = TestClient(app)

def test_openapi_schema():
    openapi_schema = app.openapi()
    # Find the Item schema in components/schemas
    item_schema = openapi_schema["components"]["schemas"]["Item"]
    print(json.dumps(item_schema, indent=2))
    assert "name_upper" in item_schema["properties"], "name_upper should be in the schema"

if __name__ == "__main__":
    try:
        test_openapi_schema()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

